### Description

This PR introduces a [new API](https://github.com/particle-iot/device-os/blob/new-event-api/sc-131168/wiring/inc/spark_wiring_cloud_event.h) for publishing and subscribing to cloud events. The new API supports sending and receiving up to 16K of data in an event.

### Examples

Publishing a text event:

```cpp
CloudEvent event;
event.name("my_event");
event.data("abc");
Particle.publish(event);
// or
Particle.publish(CloudEvent().name("my_event").data("abc"));
```

Publishing a binary-encoded event:

```cpp
CloudEvent event;
event.name("my_event");
event.data("\x01\x02\x03\x04", 4);
event.contentType(ContentType::BINARY);
Particle.publish(event);
```

Using the event instance as a regular stream:

```cpp
CloudEvent event;
event.name("my_event");
for (int i = 0; i < 10; ++i) {
    event.write("abc", 3);
}
Particle.publish(event);
```

Polling the status of an event:

```cpp
CloudEvent event;
bool done = false;

void loop() {
    if (event.isNew()) {
        event = CloudEvent().name("my_event").data("abc");
        Particle.publish(event);
    }
    if (!done) {
        if (!event.isOk()) {
            // This catches any error that might have occurred while creating or sending the event
            Log.error("Failed to send event: %d", event.error());
            done = true;
        } else if (event.isSent()) {
            Log.info("Successfully sent event");
            done = true;
        }
    }
}
```

Using a callback to receive status updates for an event:

```cpp
CloudEvent event;

void loop() {
    if (event.isNew()) {
        event = CloudEvent().name("my_event").data("abc");
        event.onStatusChange([](auto event) {
            if (!event.isOk()) {
                Log.error("Failed to send event: %d", event.error());
            } else if (event.isSent()) {
                Log.info("Successfully sent event");
            }
        });
        Particle.publish(event);
    }
}
```

