    Particle.connect();
    waitFor(Particle.connected, 60000);

    Log.info("Start sleep test");

    SystemSleepConfiguration config;

    config.mode(SystemSleepMode::HIBERNATE)
        .gpio(D8, FALLING)
        .duration(10s);

    Log.info("going to sleep");
    delay(10);

    System.sleep(config);
}
