### Problem
1. `BLE.connect()` may succeed followed by an immediate disconnected event
2. BLE service and characteristic discovery may fail

### Solution
1. Only if the connection is proven to be able to retrieve the peer's RSSI, then we add the connection to internal cache so that `BLE.connect()` returns a valid peer device
2. Gives more retries when the SDK API for service or characteristic discovery returns `NRF_ERROR_BUSY`

### Steps to Test
1. Build and flash the DUT's test app to a Gen3 device and the Peripheral's test app to either an Gen3 or Gen4 device.

### Example App

1. DUT's test app
```cpp
#include "Particle.h"

SYSTEM_MODE(SEMI_AUTOMATIC);
SYSTEM_THREAD(ENABLED);

Serial1LogHandler logHandler(115200, LOG_LEVEL_ALL);

const char* serviceUuid = "6E400000-B5A3-F393-E0A9-E50E24DCCA9E";
BlePeerDevice peer;

uint8_t test = 0;

void setup() {
}

void loop() {
    if (!BLE.connected()) {
        Log.info("Scanning...");
        BleScanResult results[20];
        ssize_t count = BLE.scan(results, 20);
        if (count > 0) {
            for (uint8_t i = 0; i < count; i++) {
                BleUuid foundServiceUUID;
                size_t svcCount = results[i].advertisingData().serviceUUID(&foundServiceUUID, 1);
                if (svcCount > 0 && foundServiceUUID == serviceUuid) {
                    if (test == 0) {
                        Log.info("---------------- 1. Auto discovery ----------------");
                        peer = BLE.connect(results[i].address()); // Automatically discover all services and characteristics on connected
                    } else if (test == 1) {
                        Log.info("---------------- 2. Services discovery ----------------");
                        peer = BLE.connect(results[i].address(), false);
                        if (peer.connected()) {
                            Vector<BleService> services = peer.discoverAllServices();

                            BleService ctrlService;
                            if (peer.getServiceByUUID(ctrlService, "6FA90001-5C4E-48A8-94F4-8030546F36FC") != true) {
                                Log.info("CTRL Service not found!");
                                while (1);
                            }
                            BleService customService;
                            if (peer.getServiceByUUID(customService, "6E400000-B5A3-F393-E0A9-E50E24DCCA9E") != true) {
                                Log.info("Custom Service not found!");
                                while (1);
                            }

                            Vector<BleCharacteristic> characteristicsOfCtrlService = peer.discoverCharacteristicsOfService(ctrlService);
                            if (characteristicsOfCtrlService.size() != 3) {
                                Log.info("Characteristics of CTRL service discovery failed!");
                                while (1);
                            }
                            Vector<BleCharacteristic> characteristicsOfCustomService = peer.discoverCharacteristicsOfService(customService);
                            if (characteristicsOfCustomService.size() != 7) {
                                Log.info("Characteristics of Custom service discovery failed!");
                                while (1);
                            }
                        }
                    } else {
                        Log.info("---------------- 3. Characteristics discovery ----------------");
                        peer = BLE.connect(results[i].address(), false);
                        if (peer.connected()) {
                            Vector<BleCharacteristic> allCharacteristics = peer.discoverAllCharacteristics();

                            BleService ctrlService;
                            if (peer.getServiceByUUID(ctrlService, "6FA90001-5C4E-48A8-94F4-8030546F36FC") != true) {
                                Log.info("CTRL Service not found!");
                                while (1);
                            }
                            BleService customService;
                            if (peer.getServiceByUUID(customService, "6E400000-B5A3-F393-E0A9-E50E24DCCA9E") != true) {
                                Log.info("Custom Service not found!");
                                while (1);
                            }

                            Vector<BleCharacteristic> characteristicsOfCtrlService = peer.characteristics(ctrlService);
                            if (characteristicsOfCtrlService.size() != 3) {
                                Log.info("Characteristics of CTRL service discovery failed!");
                                while (1);
                            }
                            Vector<BleCharacteristic> characteristicsOfCustomService = peer.characteristics(customService);
                            if (characteristicsOfCustomService.size() != 7) {
                                Log.info("Characteristics of Custom service discovery failed!");
                                while (1);
                            }
                        }
                    }
                    if (peer.connected()) {
                        test++;
                        test %= 3;
                    } else {
                        Log.info("Connection failed!");
                    }
                    break;
                }
            }
        }
    } else {
        delay(100);
        Log.info("Disconnecting...");
        BLE.disconnect(peer);
        delay(1s);
    }
}
