	let message = {
		type_id : 507, // CTRL_REQUEST_WIFI_SET_NETWORK_CREDENTIALS
		ssid: "TP-Link_F6E0",
		bssid: null,
		security: 4, //   WPA_WPA2_PSK = 4
		hidden: false,
