await p2_device.open();

let messages = [
	{
		ssid: "TP-Link_F6E0", // <-- Your hidden SSID Here
		bssid: null,
		security: 4, //   WPA_WPA2_PSK = 4
		hidden: true,
		credentials: {
			type: 1, // CredentialsType.PASSWORD
			password: "78019348". // <--- Your password here
		},
	}
]

for (let i in messages) {
	let msg = messages[i];
	console.log("Sending: ", msg);
	
