### Problem

MSoM EVT `A7`/`VBAT_MEAS` is only usable as ADC, not as digital IO

### Solution

MSoM DVT should connect both the `VBAT_MEAS` and `PA20` pins to form a more functional `A7`/`D28` pin that is capable of both ADC and digital IO

### Steps to Test

On EVT MSOM with the EVB, jumper together A7 and SOM11 to form the combined A7/VBAT_MEAS pin

### Example App

```c
#include "Particle.h"

Serial1LogHandler logHandler1(115200, LOG_LEVEL_ALL, 
{
    {
        "app", LOG_LEVEL_TRACE }, // Default logging level for all application messages
    }
);
SYSTEM_MODE(AUTOMATIC);
SYSTEM_THREAD(ENABLED);

void setup() {
}

void loop() {
    if (Serial1.available() > 0) {
        auto commandByte = Serial1.read();

        // All names for the same pin, just to make sure they all work. D26 for comparison with "normal" io
        const int pinAliases[] = {A7, D28, VBAT_MEAS, D26};
        const char * pinNames[] = {"A7", "D28", "VBAT_MEAS", "D26"};

        static int pinIndex = 0;
        static int pin = pinAliases[pinIndex];
        static const char * pinName = pinNames[0];

        switch ((char)commandByte) {
            case '1':
            {
                if (++pinIndex > 3) {
                    pinIndex = 0;
                }
                pin = pinAliases[pinIndex];
                pinName = pinNames[pinIndex];
                Log.info("Using pin number %d name %s", pin, pinName);
                break;
            }
            case '2':
            {
                int val = analogRead(pin);
                Log.info("ADC read on pin %s result %d", pinName, val);
                break;
            }
            case '3':
            {
                static bool outputHigh = true;
                Log.info("Digital write on pin %s state %d", pinName, outputHigh);

                pinMode(pin, OUTPUT);
                digitalWrite(pin, outputHigh ? HIGH : LOW);
                outputHigh = !outputHigh;
                break;
            }
            case '4':
            {
                int val = digitalRead(pin);
                Log.info("Digital read on pin %s result: %d", pinName, val);
                break;
            }
            default:
                break;
        }
    }
}
