   * A link to a Docs PR is even better!
   */
}

void loop() {
    static uint8_t i = 0;
    int analogPin = A5;
    int value = 0;
    String source;

    // Set ADC reference source
    if (i++ % 2) {
        analogSetReference(AdcReference::INTERNAL);
    } else {
        analogSetReference(AdcReference::VCC);
