SYSTEM_MODE(SEMI_AUTOMATIC);
SYSTEM_THREAD(ENABLED);

SerialLogHandler l(LOG_LEVEL_ALL);
time32_t start = 0;

void setup() {
    while (!Serial.isConnected());
    Particle.connect();
    start = Time.now();
}

void loop() {
    if (Time.now() - start > 10) {
        Particle.disconnect();
        Cellular.disconnect();
        while (1);
    }
}
