```c
#include "Particle.h"

using namespace std::placeholders;

SYSTEM_MODE(MANUAL);

SerialLogHandler log(LOG_LEVEL_INFO);

volatile uint8_t normalFunc3 = 0;
volatile uint8_t normalFunc2 = 0;
volatile uint8_t normalFunc1 = 0;
volatile uint8_t normalFunc0 = 0;
volatile uint8_t lambda3 = 0;
volatile uint8_t lambda2 = 0;
volatile uint8_t lambda1 = 0;
volatile uint8_t lambda0 = 0;

bool update = false;

void onButtonClick3(system_event_t events, int data, void* pointer) {
    normalFunc3++;
    update = true;
}
void onButtonClick2(system_event_t events, int data) {
    normalFunc2++;
}
void onButtonClick1(system_event_t events) {
    normalFunc1++;
}
void onButtonClick0() {
    normalFunc0++;
}

class Test {
public:
    void handler3(system_event_t events, int data, void* pointer) {
        count3++;
    }
    void handler2(system_event_t events, int data) {
        count2++;
    }
    void handler1(system_event_t events) {
        count1++;
    }
    void handler0() {
        count0++;
    }

    void print() {
        Log.info("Count: %d, %d, %d, %d", count3, count2, count1, count0);
    }
private:
    uint8_t count3;
    uint8_t count2;
    uint8_t count1;
    uint8_t count0;
};

Test test;

void setup() {
    while (!Serial.isConnected());
    delay(1s);

    System.on(button_click, onButtonClick3);
    System.on(button_click, onButtonClick2);
    System.on(button_click, onButtonClick1);
    System.on(button_click, onButtonClick0);

    System.on(button_click, &Test::handler3, &test);
    System.on(button_click, &Test::handler2, &test);
    System.on(button_click, &Test::handler1, &test);
    System.on(button_click, &Test::handler0, &test);

    System.on(button_click, std::bind(&Test::handler3, &test, _1, _2, _3));
    System.on(button_click, std::function<void(system_event_t, int)>(std::bind(&Test::handler2, &test, _1, _2)));
    System.on(button_click, std::function<void(system_event_t)>(std::bind(&Test::handler1, &test, _1)));
    System.on(button_click, std::function<void()>(std::bind(&Test::handler0, &test)));

    System.on(button_click, [](system_event_t events, int data, void* pointer) {
        lambda3++;
    });
    System.on(button_click, [](system_event_t events, int data) {
        lambda2++;
    });
    System.on(button_click, [](system_event_t events) {
        lambda1++;
    });
    System.on(button_click, []() {
        lambda0++;
    });
}

void loop() {
    if (update) {
        update = false;
        Log.info("Normal function: %d, %d, %d, %d", normalFunc3, normalFunc2, normalFunc1, normalFunc0);
        Log.info("Lambda: %d, %d, %d, %d", lambda3, lambda2, lambda1, lambda0);
        test.print();
    }
}
