    float soc = gauge.getSoC();
    system_tick_t end = micros();
    LOG(TRACE, "FuelGauge SoC: %4.2f %%, delta T: %d us", soc, end - start);

    PMIC pmic;
    start = micros();
    pmic.getVersion();
    end = micros();
    LOG(TRACE, "PMIC delta T: %d us", end - start);

    delay(1000);
}
