void setup() {
    // Apply custom configuration
    SystemPowerConfiguration conf;
    // We are specifically using the values that don't exactly match what
    // the PMIC can use as settings and validating that they are being
    // mapped correctly later on.
    conf.powerSourceMaxCurrent(550) // Set maximum current the power source can provide (applies only when powered through VIN)
        .powerSourceMinVoltage(4300) // Set minimum voltage the power source can provide (applies only when powered through VIN)
        .batteryChargeCurrent(850) // Set battery charge current
        .batteryChargeVoltage(4210) // Set battery termination voltage
        .feature(SystemPowerFeature::PMIC_DETECTION) // For platforms with external PMIC/FuelGauge (e.g. BSoM), enables
                                                     // runtime PMIC presence detection and enables power management
                                                     // if found.
                                                     // NOTE: This supersedes the System.enable(SYSTEM_FLAG_PM_DETECTION) call
        .feature(SystemPowerFeature::USE_VIN_SETTINGS_WITH_USB_HOST) // For the cases where the device is powered through VIN
                                                                     // but the USB cable is connected to a USB host, this feature flag
                                                                     // enforces the voltage/current limits specified in the configuration
                                                                     // (where by default the device would be thinking that it's powered by the USB Host)
    int res = System.setPowerConfiguration(conf); // returns SYSTEM_ERROR_NONE (0) in case of success

    // To restore the default configuration
    System.setPowerConfiguration(SystemPowerConfiguration());

    // Settings are persisted.
}

void loop() {
