### Problem

Linking in some code written in another language. (I'm testing this with Rust)

### Solution

Just linking in the `*.a` from `lib-static/` directory.
It's the responsibility of a user to `extern "C"`-declare the functions in these static archives.

### Example App

`main.ino`:
```c
extern "C" void particle_setup();
void setup() {
  particle_setup();
}

extern "C" void particle_loop();
void loop() {
  particle_loop();
}
```

`src/lib.rs`:
```rust
#![no_std]
#![feature(alloc_error_handler, core_intrinsics)]

#[macro_use]
extern crate bitflags;
extern crate alloc;
extern crate panic_abort;

use cstr_core::CString;
use cstr_core::c_char;
use alloc::alloc::{GlobalAlloc, Layout};
use core::panic::PanicInfo;

struct MyAllocator;

extern {
    fn malloc(size: usize) -> *mut u8;
    fn free(pre: *mut u8);
}

unsafe impl GlobalAlloc for MyAllocator {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 { malloc(layout.size()) }
    unsafe fn dealloc(&self, ptr: *mut u8, _layout: Layout) { free(ptr); }
}

#[global_allocator]
static A: MyAllocator = MyAllocator;

#[alloc_error_handler]
fn alloc_error_handler(_layout: Layout) -> ! {
    unsafe { core::intrinsics::abort() };
}

#[allow(non_camel_case_types)]
pub type c_int = i32;

bitflags! {
    struct PublishFlags: u8 {
        const PRIVATE = 1;
        const NO_ACK = 2;
        const WITH_ACK = 8;
    }
}

extern {
    //     static particle::Future<bool> publish_event(const char *eventName, const char *eventData, int ttl, PublishFlags flags);
    fn _ZN10CloudClass13publish_eventEPKcS1_iN8particle5FlagsI15PublishFlagTypehEE(
        event_name: *const c_char, 
        event_data: *const c_char, 
        ttl: c_int,
        publish_flags: u8
    );
}

fn particle_publish(event_name: &str, event_data: &str, ttl: i32, flags: PublishFlags) {
    unsafe {
        _ZN10CloudClass13publish_eventEPKcS1_iN8particle5FlagsI15PublishFlagTypehEE(
            CString::new(event_name).unwrap().as_ptr(),
            CString::new(event_data).unwrap().as_ptr(),
            ttl.into(), flags.bits()
        );
    }
}

#[no_mangle]
pub fn particle_setup() {
    particle_publish("test/rust", "Hello from Rust", 0, PublishFlags::PRIVATE);
}

#[no_mangle]
pub fn particle_loop() {
}
