    Particle.connect();
    waitUntil(Particle.connected);
    delay(1000);
    LOG(TRACE, "Free connected %lu", System.freeMemory());
    Particle.publish("test");
    delay(1000);
    WiFi.disconnect();
    waitUntil(wifinotready);
    delay(1000);
    LOG(TRACE, "Free disconnected %lu", System.freeMemory());
}

```

